function materialSplitSection(category,view,headers,rows,rowFn,valueVisible,index){
 const meta=view==='stock'?`${new Set(rows.map(i=>i.warehouse_id)).size} 个库房 · ${new Set(rows.map(i=>i.id)).size} 种物料${valueVisible?' · 金额 '+amount(rows.reduce((n,i)=>n+Number(i.value_cents||0),0)):''}`:`${rows.length} 笔流水${valueVisible?' · 成本 '+amount(rows.reduce((n,e)=>n+Number(e.cost_cents||0),0)):''}`;
 return `<section class="material-split${index?' material-split-next':''}"><div class="material-split-head"><h3>${esc(category)}${view==='stock'?'库存':'流水'}</h3><span>${meta}</span></div>${resourceTable(headers,rows.map(rowFn).join(''))}</section>`;
}
document.addEventListener('click',e=>{const view=e.target.closest('[data-material-view]');if(view){requestPageTransition(()=>{materialView=view.dataset.materialView;materialState='';render();});}if(e.target.closest('[data-material-clear]')){materialCategory='';materialWarehouse='';materialLedgerFilter='';materialState='';materialKind='';materialSearch='';render();}});
