 if(f.dataset.kind==='review'){b.decision=decision;b.evidence_checked=b.evidence_checked==='on';if(decision==='return'&&!b.note.trim())throw Error('请填写退回原因，便于会计核对并重录');if(decision==='approve'&&!b.evidence_checked)throw Error('请先核对费用金额、收款方与原始凭据，并勾选确认');}
