async function saveResourceForm(){if(!data.capabilities?.includes('material-warehouses-v1')){err(Error('服务尚未更新分库与成本功能，请重启服务并刷新页面后再提交'));return;}const f=$('#resource-form');if(!f||!f.reportValidity())return;if(f.dataset.kind==='attribute'&&!data.capabilities?.includes('material-source-allocation-v1')){err(Error('归集更正服务尚未更新，请重启服务并重新读取页面'));return;}syncMaterialCostChoice(f);const kind=f.dataset.kind,body={...Object.fromEntries(new FormData(f)),...JSON.parse(f.dataset.reference),request_key:f.dataset.requestKey,revision:resourceData().revision};if(kind==='item'){body.active=body.active==='true';body.default_product_ids=[...f.querySelectorAll('[name=default_product_ids]:checked')].map(x=>x.value);body.pinned=!!f.elements.pinned.checked;body.packaging_rates=Object.fromEntries([...f.querySelectorAll('[data-packaging-rate]')].filter(e=>e.value!=='').map(e=>[e.dataset.packagingRate,e.value]));}const message={item:'物料资料已保存',material:'库存流水已登记',expense:'费用已登记，待出纳核对',byproduct:'豆渣销售已登记',receive:'到账已登记',period:'成本月份状态已更新',void:'已作废，原记录保留',restore:'已恢复，重新计入台账',value:'入库金额已补录',attribute:'成本归集已更正'}[kind]||'台账已更新';await perform(()=>submit('/api/resources/'+kind,body,message));}
function materialDeleteDialog(record){openDialog('删除物料 · '+record.name,`<form id="resource-form" data-kind="item-delete" data-reference="${esc(JSON.stringify({id:record.id,version:record.version}))}" data-request-key="${erpRequestKey()}"><div class="form-grid">${resourceField('删除原因','reason','text','','required maxlength="500"')}</div></form><p class="callout">只有从未产生库存流水、也未被采购单引用的自建物料可以删除；系统预置物料、有库存或有流水的物料请改为「停用」。删除不可恢复，操作留审计记录。</p>`,'物料档案','<button class="button" data-act="close">取消</button><button class="button danger" data-resource-delete-confirm>确认删除</button>');}
async function saveMaterialDelete(){const f=$('#resource-form');if(!f?.reportValidity())return;await perform(()=>submit('/api/resources/item-delete',{...Object.fromEntries(new FormData(f)),...JSON.parse(f.dataset.reference),request_key:f.dataset.requestKey},'物料已删除'));}
document.addEventListener('click',e=>{const historyAct=e.target.closest('[data-material-history-act]');if(historyAct){const id=($('#material-history-entry')?.value||'').trim();if(!id){notify('请先填写历史流水单号');return;}openResourceForm(historyAct.dataset.materialHistoryAct,id,'material').catch(err);return;}const b=e.target.closest('[data-resource-act]');if(b)openResourceForm(b.dataset.resourceAct,b.dataset.id,b.dataset.ledger,b.dataset.warehouse).catch(err);const del=e.target.closest('[data-resource-delete]');if(del){const rec=resourceData().items.find(i=>i.id===del.dataset.resourceDelete);if(rec)materialDeleteDialog(rec);return;}if(e.target.closest('[data-resource-delete-confirm]')){saveMaterialDelete();return;}if(e.target.closest('[data-resource-save]'))saveResourceForm();if(e.target.closest('[data-resource-refresh]'))refresh().catch(err);});
document.addEventListener('change',e=>{if(e.target.name==='material_attribution')syncMaterialCostChoice(e.target.form);if(e.target.closest('#resource-form')&&['material_id','kind','warehouse_id','business_date'].includes(e.target.name))syncResourcePlacement();if(e.target.closest('#resource-form')&&e.target.name==='category'&&e.target.value==='cold-power'){const f=$('#resource-form');f.elements.department.value='豆腐线';f.elements.product_id.value=data.products.find(p=>p.name==='冻豆腐')?.id||'';notify('冷库电费归冻豆腐专属成本；未建产品档案时保留成本对象，不分摊到其他产品');}if(e.target.id==='material-warehouse'){materialWarehouse=e.target.value;render();}if(e.target.id==='resource-month'){resourcesMonth=e.target.value;for(const key of Object.keys(resourceLedgerState))delete resourceLedgerState[key];render();}if(e.target.id==='material-category'){materialCategory=e.target.value;render();}if(e.target.id==='material-ledger-filter'){materialLedgerFilter=e.target.value;render();}});

function resourceHomeSummary(){const r=resourceData(),visible=p=>!data.auth_user||data.access_catalog.modules.some(m=>m.page===p&&moduleVisible(m)),cards=[];
 if(visible('materials')){const low=r.items.filter(i=>i.low_stock&&i.has_entries);cards.push(['materials','原辅料库存',`${low.length} 种低库存`,`${r.items.filter(i=>i.active).length} 种在管物料 · 查看库存与领用`]);}
 if(visible('expenses')){const state=r.expense_history_deferred?resourceLedgerRead('home-expenses','expenses',{period:today().slice(0,7),page_size:1}):null;cards.push(['expenses','本月成本',state?(state.value?amount(state.value.summary.total_cents):state.error?'读取失败':'读取中'):amount(r.expenses.filter(e=>resourceActive(e)&&String(e.period)===today().slice(0,7)).reduce((s,e)=>s+e.amount_cents,0)),'人工 / 能源 / 配送 / 制造费用']);}
 if(visible('byproducts')){const state=byproductSummary(today().slice(0,7));cards.push(['byproducts','本月豆渣收入',state.value?amount(state.value.month_cents):state.error?'读取失败':'读取中','销售与到账分开追踪']);}
 if(visible('analytics'))cards.push(['analytics','经营看板','销售 · 库存 · 成本','销售趋势、客户排行、应收账龄']);
 return resourcePanel('各业务系统看盘',`<div class="home-workflow">${cards.map(([p,t,v,sub])=>`<button class="home-task" data-page="${p}"><strong>${t}</strong><b>${v}</b><p>${sub}</p><span>查看明细 ↗</span></button>`).join('')}</div>`);
}
function processingCostPanel(state){
 if(!state?.value)return resourcePanel('转加工成本估算',state?.error?'<p class="empty">'+esc(state.error)+'</p>':'<p class="empty">正在读取本月转加工成本…</p>');
 const c=state.value,status=c.status==='估算'?'<span class="badge green">估算</span>':'<span class="badge orange">'+esc(c.status)+'</span>';
 return resourcePanel('转加工成本估算',`<p class="panel-explanation">直接成本按每批来源产品当日平均出品率折算黄豆投入，再乘当日大豆均价；非专属间接成本按本月全部产出净重分摊，转加工产出按自身净重承担。结果为管理估算，不替代会计月结。${status}</p>`+metrics([['来源投入',num(c.source_input_kg),'kg','白干 / 豆皮等'],['对应黄豆',num(c.soy_input_kg),'kg','按来源出品率折算'],['直接成本',amount(c.direct_cost_cents),'', '大豆成本'],['间接分摊',amount(c.indirect_cost_cents),'','本月非专属'],['合计',amount(c.total_cost_cents),'','批次：'+c.batch_count]])+resourceTable(['产出产品','产出数量','产出净重','对应黄豆','出品率','直接成本','间接分摊','合计','单位成本'],(c.outputs||[]).map(o=>`<tr><td>${esc(o.product_name)}</td><td>${num(o.qty)}${esc(o.unit)}</td><td>${num(o.net_kg)}kg</td><td>${num(o.soy_kg)}kg</td><td>${o.yield_kg==null?'待核算':num(o.yield_kg)+' kg/kg'}</td><td>${o.pending?'待结转':amount(o.direct_cents)}</td><td>${amount(o.indirect_cents||0)}</td><td>${o.pending?'待结转':amount(o.cost_cents)}</td><td>${o.unit_cost_yuan_per_kg==null?'—':num(o.unit_cost_yuan_per_kg)+' 元/kg'}</td></tr>`).join(''),'本月还没有转加工产出。'));
}
function resourceProductionPage(){return monthlyProductionPage();}
function materialAllocationPanel(state){if(!state||state.loading)return resourcePanel('大豆成本分摊','<p class="empty" role="status">正在读取分摊依据…</p>');if(state.error)return resourcePanel('大豆成本分摊',`<p class="callout">读取失败：${esc(state.error)}。请重新读取页面。</p><button class="button" data-resource-refresh>重新读取</button>`);const r=state.value;return resourcePanel('大豆成本分摊',`<p class="panel-explanation">实际领豆成本 ${amount(r.total_cents)} · 已分摊 ${amount(r.allocated_cents)} · 待核对 ${amount(r.unallocated_cents)}。同一产品来自两套系统的成本合并计入；分摊精确到分。</p><details><summary>查看每日来源与分摊依据</summary>${resourceTable(['日期 / 来源','实际领豆','领豆成本','状态 / 下一步'],r.pools.filter(p=>p.status!=='无领用').map(p=>`<tr><td>${esc(p.business_date)}<small>${esc(p.system_name)}</small></td><td>${num(p.issued_kg)} kg</td><td>${amount(p.cost_cents)}</td><td><span class="badge ${p.status==='已分摊'?'green':'orange'}">${esc(p.status)}</span><small>${p.reasons.map(esc).join('；')}</small></td></tr>`).join(''))}${resourceTable(['日期 / 产品','供浆来源','分摊用豆','分摊金额','分摊依据'],r.allocations.map(a=>`<tr><td>${esc(a.business_date)}<small>${esc(a.product_name)}</small></td><td>${esc(a.system_name)}</td><td>${num(a.allocated_kg)} kg</td><td>${amount(a.cost_cents)}</td><td>${esc(a.basis)}<small>折豆基数 ${num(a.basis_kg)} kg</small></td></tr>`).join(''))}</details>`,'按当天生产配置执行：占比法用各产品“缸数 × 每缸干豆”作为权重，分配该系统实际领豆；余量法先给其他产品分配折豆量，剩余实际领豆和成本归余量接收产品。接收产品由配置指定，不固定为豆皮。折豆不是实际称重；缺项及转出超过领豆时转待核对，不强行分摊。');}

function productSoyCostCell(report,pid){const rows=report.allocations.filter(a=>a.product_id===pid),pending=report.pools.some(p=>p.reasons.length&&(p.affected_product_ids?.includes(pid)||p.system==='unknown'));return (rows.length?amount(rows.reduce((n,a)=>n+a.cost_cents,0)):pending?'—':amount(0))+(pending?'<small>供浆数据待核对</small>':'');}

function materialCostSettingsForm(item){
 const mode=item?.cost_mode||'legacy';return resourceSelect('成本方式','cost_mode',[['legacy','沿用历史领用 / 摊销规则'],['issue','领用即耗'],['count','月末盘点实耗'],['amortize','跨月摊销']].map(([v,t])=>`<option value="${v}" ${mode===v?'selected':''}>${t}</option>`).join(''))+resourceField('成本方式生效月份','cost_from','month',item?.cost_from||today().slice(0,7),'required')+resourceField('每库存单位折合袋数','bag_units','number',item?.bag_units||'1','min="0.001" step="0.001" required')+`<fieldset class="wide"><legend>包装用量核对（每发货单位用几个袋；非包材留空）</legend><div class="form-grid">${data.products.map(p=>`<label class="field"><span class="field-label">${esc(p.name)} · 个/${esc(p.unit)}</span><input type="number" min="0.001" step="0.001" data-packaging-rate="${esc(p.id)}" value="${esc(item?.packaging_rates?.[p.id]||'')}"></label>`).join('')}</div><p class="help-text">例如物料按包入库、每包100个袋，折合袋数填100；产品每包使用1个袋，用量填1。产量仅用于核对和分配，实际耗用以盘点为准。</p></fieldset>`;
}
